style.css:
@-moz-document domain("sohu.com") {
/* ============================================================
     Palette
     base bg          #14181d
     elevated surface #1c2128
     header/footer    #0d1117
     border subtle    #262c33
     border component #2d333b
     text primary     #e6edf3
     text reading     #c8d0d9
     text muted       #8b949e
     link/accent      #5fb0e6 (hover #9bd4ff)
     brand orange     #ff7a45 (Sohu red-orange, tuned for dark)
     ============================================================ */

  :root {
    color-scheme: dark;
  }

  /* ---------- Base ---------- */
  html,
  body {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }

  /* Common page wrappers that carry a hardcoded white background */
  .article-page,
  .index,
  .main-content,
  .content,
  #main,
  .wrapper,
  .page,
  .container,
  .top-box-wrapper,
  .wrapper-box,
  .main-box,
  .box-wrapper {
    background-color: transparent !important;
  }

  /* classic-homepage / Sohu-video promo strip (light gradient art) */
  .swf-top,
  .swf-top a,
  .swf-banner {
    background-color: #1c2128 !important;
    background-image: none !important;
  }

  /* light-grey filler tiles / plugin modules on the home grid */
  .content-other-item,
  .other-item,
  .grey-box,
  .gray-box,
  .title-cut,
  .picture-group,
  .author-subscribe-area,
  .fun-frag,
  .extend-mod,
  .other-modA,
  .other-modB,
  .plugin,
  .yule-play,
  .sports-match,
  .stock-tabs-c,
  .stock-box,
  .fun-list,
  .mod-box {
    background-color: #1c2128 !important;
  }

  /* Soften every light border into a subtle dark one */
  * {
    border-color: #262c33 !important;
  }

  /* ---------- Header / top nav ---------- */
  .sohu-head,
  header,
  .header,
  .area-header,
  .tbl-explore-more-site-header {
    background-color: #0d1117 !important;
    color: #e6edf3 !important;
  }

  .sohu-head a,
  header a,
  .header a,
  .sohu-head-box,
  .top-head,
  .head-item,
  .head-item a,
  .login,
  .login-area,
  .login-area a {
    color: #e6edf3 !important;
    background-color: transparent !important;
  }

  .sohu-head a:hover,
  header a:hover,
  .head-item a:hover {
    color: #9bd4ff !important;
  }

  .divide-line {
    background-color: #2d333b !important;
  }

  /* primary nav bar (channels) */
  .nav,
  .nav.area,
  .menu,
  .nav-list,
  .channel,
  .channel-list {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  .nav a,
  .menu a,
  .channel a {
    color: #c4cdd6 !important;
  }

  .nav a:hover,
  .menu a:hover,
  .channel a:hover {
    color: #ff7a45 !important;
  }

  /* ---------- Search box ---------- */
  .search-input,
  input[type="text"],
  input[type="search"],
  input.text,
  .search input,
  textarea {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  .search-input::placeholder,
  input::placeholder,
  textarea::placeholder {
    color: #8b949e !important;
    opacity: 1 !important;
  }

  .search-btn,
  .search button,
  button.search {
    background-color: #ff7a45 !important;
    color: #14181d !important;
    border-color: #ff7a45 !important;
  }

  /* ---------- Home aggregator grid ---------- */
  .main-left,
  .main-right,
  .left,
  .right,
  .scroll,
  .index-focus,
  .focus,
  .swiper-focus,
  .block,
  .news-box,
  .feed,
  .feed-list,
  .feed-content,
  .list,
  .card {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  /* section / block labels + hardcoded-dark headlines/metadata */
  .title,
  .block-title,
  .focus-title,
  .news-title,
  .titleW,
  .tab,
  .col-title,
  .other-title,
  .tt,
  .txt,
  .focus-t,
  .swf-tt,
  h2,
  h3 {
    color: #e6edf3 !important;
  }

  /* read counts / muted metadata that ship hardcoded grey */
  .read-num,
  .read-count,
  .num,
  .source-name,
  em.read-num {
    color: #8b949e !important;
  }

  /* headline links */
  a,
  .title a,
  .news-title a,
  .feed a,
  .list a {
    color: #c4cdd6 !important;
  }

  a:hover {
    color: #9bd4ff !important;
  }

  /* hot-list / ranking widgets */
  .rank,
  .ranklist,
  .hot,
  .news-rank,
  [class*="rank"],
  [class*="hot-list"] {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  /* thumbnails keep their own colors; just no white tile behind them */
  .pic,
  .img-do,
  .ad-focus,
  .thumb,
  .pic-box {
    background-color: transparent !important;
  }

  /* home right-column widget (e.g. "北京要闻"): each headline row is an
     a.shadow with a hardcoded rgb(249,249,249) pill bg — flatten it.
     The .qrcode stays white (it's a scannable QR code, like a logo). */
  a.shadow {
    background-color: transparent !important;
  }

  /* ---------- Article reader (the key surface) ---------- */
  #article-container,
  .article-page .main,
  .left.main,
  .text,
  .article-info {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  /* the long-form body — soft off-white, comfortable for reading */
  article,
  #mp-editor,
  .article,
  #mp-editor p,
  .article p,
  .text p,
  #mp-editor span,
  .article span,
  #mp-editor div,
  .article div,
  #mp-editor font,
  .article font,
  #mp-editor li,
  .article li {
    color: #c8d0d9 !important;
    background-color: transparent !important;
  }

  /* title */
  .article-page h1,
  #article-container h1,
  .article-title,
  h1 {
    color: #e6edf3 !important;
  }

  /* byline / date / source / author */
  .article-info,
  .article-info a,
  .time,
  .source,
  .author,
  .media-name,
  .user-info,
  .statement,
  .declare {
    color: #8b949e !important;
  }

  .article-info a:hover,
  .media-name a:hover {
    color: #9bd4ff !important;
  }

  /* blockquotes */
  #mp-editor blockquote,
  .article blockquote,
  blockquote {
    background-color: #1c2128 !important;
    border-left-color: #2d333b !important;
    color: #c8d0d9 !important;
  }

  /* in-body links + the "返回搜狐，查看更多" link */
  #mp-editor a,
  .article a,
  .text a,
  .backword,
  .show-all {
    color: #5fb0e6 !important;
  }

  #mp-editor a:hover,
  .article a:hover,
  .backword:hover {
    color: #9bd4ff !important;
  }

  /* code inside articles */
  #mp-editor pre,
  .article pre,
  #mp-editor code,
  .article code {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* ---------- Author card / sidebar widgets on the article page ---------- */
  .author-card-c,
  .author-card,
  .author-info,
  .author-subscribe,
  .godR,
  .hot-article,
  .hot-article.bord,
  .side-box,
  .sidebar-box {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
  }

  /* right-hand article sidebar wrapper */
  .right-side-abroad,
  .right-side,
  .area-side {
    background-color: transparent !important;
  }

  /* author / editor name keeps the Sohu red identity, lifted for dark */
  .editor-name,
  .username,
  .unlogin-text,
  .author-name {
    color: #ff6a5a !important;
  }

  /* ---------- Related stories / recommendations ---------- */
  .recommend,
  .relevant,
  .related,
  .recommend-list,
  .area-business,
  .box,
  .statement,
  .recommend-art,
  .sub-art {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  /* related-list headings, source names and subtitles ship hardcoded dark */
  .recommend .name,
  .relevant .name,
  .related .name,
  .recommend-art .name,
  .hot-article .name,
  .groom-read .name,
  .godR .name,
  .author-card-c .name,
  .right-side-abroad .name,
  .recommend h2,
  .recommend h3,
  .recommend-title {
    color: #e6edf3 !important;
  }

  .sub-art,
  .recommend .sub-art,
  .groom-read .sub-art,
  .recommend .desc,
  .recommend-art .desc {
    color: #c4cdd6 !important;
  }

  .recommend a,
  .relevant a,
  .related a,
  .hot-article a {
    color: #c4cdd6 !important;
  }

  .recommend a:hover,
  .relevant a:hover {
    color: #9bd4ff !important;
  }

  /* ---------- Comments ---------- */
  #comment_area,
  .comment-area,
  .comment,
  .comment-list,
  .comment-item,
  .cmt-item,
  .reply,
  .comment-tabs,
  .comment-head {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  /* comment tab labels (最新评论 / 热门评论) ship hardcoded near-black */
  .tab-item,
  .comment-tab,
  .comment-tab span,
  .comment-tabs .tab,
  .comment-head .tab,
  .comment-title {
    color: #c4cdd6 !important;
  }

  .tab-item.active,
  .comment-tab .active,
  .comment-tabs .tab.active {
    color: #e6edf3 !important;
  }

  .comment-item .name,
  .comment .name,
  .cmt-name {
    color: #e6edf3 !important;
  }

  .comment-item .content,
  .comment .content,
  .cmt-content {
    color: #c8d0d9 !important;
  }

  .comment-item .time,
  .comment .time {
    color: #8b949e !important;
  }

  /* "推荐阅读" recommended-reading heading (#groomRead) ships hardcoded near-black */
  .groom-read,
  .groom-read .title,
  .groom-read .title span,
  .recommend-read,
  .read-title {
    color: #c4cdd6 !important;
  }

  .groom-read .title,
  .groom-read .title span {
    color: #e6edf3 !important;
  }

  /* like counter ("首赞" / read counts) + author-column metadata */
  .article-like,
  .article-like .like-text,
  .like-text,
  .like-num,
  .praise-num,
  em.read-num,
  .read-num em {
    color: #8b949e !important;
  }

  /* ---------- Sidebars ---------- */
  .area-side,
  .side,
  .sidebar,
  aside {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  /* ============================================================
     Channel / category pages (news.sohu.com, business.sohu.com, …)
     A separate modern template: the whole page lives under #Index,
     content blocks are id="block2..36" / id="TPL*_pc_*" / id="FS*" /
     id="Block_*" / id="ChannelNavigation*" with hashed timestamps, and
     the layout grid is built from classless wrapper <div>s. White is
     carried by those wrappers + per-element hardcoded near-black text.
     Neutralize the whole #Index subtree to the dark base, then
     re-establish opaque surfaces on floating menus / inputs / footer.
     ============================================================ */
  #Index,
  #Index > div,
  #Index div[id^="block"],
  #Index div[id^="Block_"],
  #Index div[id^="TPL"],
  #Index div[id^="FS"],
  #Index div[id^="Navigator"],
  #Index div[id^="ChannelNavigation"],
  #Index div:not([class]),
  #Index .single-image-text,
  #Index .imageBox,
  #Index .textBox,
  #Index .image-img-content,
  #Index .item_img,
  #Index .cover-image,
  #Index .left,
  #Index a.swf-top,
  #Index [class*="Contsize"],
  #Index .navigatorContainer,
  #Index .cbd-recommend,
  #Index .mention,
  #Index .zx {
    background-color: transparent !important;
  }

  /* business.sohu.com stock widgets carry their own white panels */
  #Index .searchForm,
  #Index .stock-info,
  #Index .stock-c,
  #Index .stock-c .content {
    background-color: #1c2128 !important;
  }

  /* opaque dark surfaces: top channel-nav header, stock ticker widgets,
     PWA "add to desktop" promo, side plugin tiles, page footer */
  .nav_header,
  .nav_container,
  .navigation-head,
  .stock-tabs-c,
  .stock-box,
  .stock-zs,
  .add-desktop,
  .add-desktop-c,
  .pwa,
  .side-wrap-plugin-bacground,
  .plugin-side-right,
  #hot-news-focus-region,
  .PCBottomCopyright {
    background-color: #14181d !important;
  }

  /* floating channel-nav "more" dropdown stays solid + opaque */
  .navigation-more-list,
  .navigation-more-show,
  .navigation-more-box {
    background-color: #1c2128 !important;
  }

  /* channel search field (rgb(242,242,242)) */
  .search-input-wrapper,
  input.search-input {
    background-color: #1c2128 !important;
  }

  #Index input.search-input {
    color: #e6edf3 !important;
  }

  /* channel text: the template hardcodes near-black per element, so
     lift every text node under #Index (and the nav header / footer)
     to a readable body color */
  #Index,
  #Index *,
  .nav_header,
  .nav_header *,
  .nav_container *,
  .navigation-more-list *,
  .PCBottomCopyright,
  .PCBottomCopyright * {
    color: #c4cdd6 !important;
  }

  /* headlines + section titles brighter */
  #Index .ImageTextCover,
  #Index .shadow,
  #Index .title-text,
  #Index .item-title,
  #Index .tpl-middle-title-left,
  #Index .tpl-middle-title-text,
  #Index h1,
  #Index h2,
  #Index h3,
  #Index .title {
    color: #e6edf3 !important;
  }

  /* active channel nav tab + selected feed tab keep the Sohu accent */
  .nav_item.nav_active,
  #Index .cur.focus-tab,
  #Index .text-info-active {
    color: #ff7a45 !important;
  }

  /* ---------- Cards / elevated panels that keep a real background ---------- */
  .box-shadow,
  .panel,
  .module,
  .widget {
    background-color: #1c2128 !important;
  }

  /* ---------- Footer ---------- */
  .footer,
  #footer,
  .footer.area,
  .copyright,
  .area-footer {
    background-color: #0d1117 !important;
    color: #8b949e !important;
  }

  .footer a,
  #footer a,
  .copyright a {
    color: #8b949e !important;
  }

  .footer a:hover,
  #footer a:hover {
    color: #c4cdd6 !important;
  }

  /* ---------- Brand accent ---------- */
  /* Sohu uses a red-orange identity; keep the hue, tune for dark */
  .backword,
  .logo-text,
  .more-link {
    color: #ff7a45 !important;
  }

  ::selection {
    background-color: #ff7a45 !important;
    color: #14181d !important;
  }
}
